);
CREATE TABLE `products` (
	`id` int AUTO_INCREMENT NOT NULL,
	`slug` varchar(120) NOT NULL,
	`name` varchar(160) NOT NULL,
	`tagline` varchar(255) NOT NULL DEFAULT '',
	`category_id` int,
